import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import ast, glob
bad = []
for f in sorted(glob.glob('_tools/kg_*.py')):
    if f.endswith('kg_base.py'): continue
    for n in ast.parse(open(f, encoding='utf-8').read()).body:
        if isinstance(n, ast.FunctionDef) and n.name in ('git', 'rev_parse', 'git_run'):
            bad.append(f + ':' + n.name)
print('kg_ modules that define their own git helper:', bad); sys.exit(1 if bad else 0)
